def test_orthogonal_grid_neumann():
    """Test orthogonal grid with von Neumann neighborhood."""
    width = 10
    height = 10
    grid = OrthogonalVonNeumannGrid((width, height), torus=False, capacity=None)

    assert len(grid._cells) == width * height

